def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def kruskal_mst(n, edges, a, b):
    parent = list(range(n))
    rank = [0] * n
    mst = []
    edges.sort(key=lambda item: item[2])

    i = 0
    e = 0
    while e < n - 1:
        while i < len(edges) and (edges[i][2] == a or edges[i][2] == b):
            u, v, w = edges[i]
            i += 1
            x = find(parent, u)
            y = find(parent, v)
            if x != y:
                union(parent, rank, x, y)
                mst.append((u, v, w))
                e += 1
                if e == n - 1:
                    break
        if e < n - 1:
            return float('inf')

    return sum(w for u, v, w in mst)

def shortest_path(n, mst, start):
    visited = [False] * n
    distance = [float('inf')] * n
    distance[start] = 0
    parent = [-1] * n

    for _ in range(n):
        u = min(range(n), key=lambda x: distance[x] and not visited[x])
        visited[u] = True

        for v, w in mst:
            if u == v[0] and not visited[v[1]]:
                if distance[u] + w < distance[v[1]]:
                    distance[v[1]] = distance[u] + w
                    parent[v[1]] = u
            elif u == v[1] and not visited[v[0]]:
                if distance[u] + w < distance[v[0]]:
                    distance[v[0]] = distance[u] + w
                    parent[v[0]] = u

    return distance

results = []
