def is_valid_sequence(sequence):
    if sequence[0] != 1:
        return False
    if sum(sequence) % 2 != 1:
        return False
    return True

def construct_trees(sequence):
    if sequence[0] != 1:
        return None, None
    if sum(sequence) % 2 != 1:
        return None, None

    # Try to construct the first tree
    tree1 = [0] * (sum(sequence) + 1)
    queue = [(0, 1)]
    index = 1
    while queue:
        parent, count = queue.pop(0)
        for _ in range(count):
            tree1[index] = parent
            index += 1
            if index < len(sequence):
                queue.append((index, sequence[index]))

    # Try to construct the second tree
    tree2 = [0] * (sum(sequence) + 1)
    queue = [(0, 1)]
    index = 1
    while queue:
        parent, count = queue.pop(0)
        for _ in range(count):
            tree2[index] = parent
            index += 1
            if index < len(sequence):
                queue.append((index, sequence[index]))

    # Ensure the trees are non-isomorphic
    if tree1 == tree2:
        return None, None

    return tree1, tree2

if not is_valid_sequence(sequence):
    print("ambiguous")
    sys.exit()

tree1, tree2 = construct_trees(sequence)

if tree1 is None or tree2 is None:
    print("ambiguous")
